 32	pub enum FileFilter {
 33	    GeoJson,
 34	    Rmp,
 35	    All,
 36	}
 37	
 38	impl FileFilter {
 39	    pub fn matches(&self, path: &std::path::Path) -> bool {
 40	        let ext = path.extension().and_then(|e| e.to_str());
 41	        match self {
 42	            FileFilter::GeoJson => matches!(ext, Some("geojson") | Some("json")),
 43	            FileFilter::Rmp => matches!(ext, Some("rmp")),
 44	            FileFilter::All => true,
 45	        }
 46	    }
 47	
 48	    pub fn description(&self) -> &str {
 49	        match self {
 50	            FileFilter::GeoJson => "*.geojson, *.json",
 51	            FileFilter::Rmp => "*.rmp",
 52	            FileFilter::All => "*.*",
 53	        }
 54	    }
 55	}
