240	impl std::fmt::Display for Status {
241	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
242	        match self {
243	            Status::Ready => write!(f, "Ready"),
244	            Status::Running { progress, message } => {
245	                write!(f, "{}% - {}", progress, message)
246	            }
247	            Status::Done(msg) => write!(f, "{}", msg),
248	            Status::Error(msg) => write!(f, "Error: {}", msg),
249	        }
250	    }
251	}
