434	    pub fn start_file_browser(&mut self, field: InputField) {
435	        let previous = self.current_view.clone();
436	        let mut browser = FileBrowser::new(field, previous);
437	        if let Err(e) = browser.refresh_entries() {
438	            self.log(
439	                LogLevel::Error,
440	                format!("Failed to open file browser: {}", e),
441	            );
442	            return;
443	        }
444	        self.file_browser = Some(browser);
445	        self.current_view = View::FileBrowser;
446	        self.log(LogLevel::Info, "File browser opened");
447	    }
