449	    pub fn close_file_browser(&mut self, selected_path: Option<PathBuf>) {
450	        let previous_view = self
451	            .file_browser
452	            .as_ref()
453	            .map(|b| b.previous_view.clone())
454	            .unwrap_or(View::Home);
455	
456	        if let Some(path) = selected_path {
457	            let path_str = path.to_string_lossy().to_string();
458	
459	            if let Some(browser) = &self.file_browser {
460	                match browser.target_field {
461	                    InputField::InputFile => {
462	                        self.input_file = Some(path_str.clone());
463	                        if self.output_file.is_none() {
464	                            let out = path_str
465	                                .replace(".geojson", ".rmp")
466	                                .replace(".json", ".rmp");
467	                            self.output_file = Some(out);
468	                        }
469	                        self.log(
470	                            LogLevel::Success,
471	                            format!("Input file selected: {}", path_str),
472	                        );
473	                        self.current_view = View::Compile;
474	                    }
475	                    InputField::OutputFile => {
476	                        self.output_file = Some(path_str.clone());
477	                        self.log(
478	                            LogLevel::Success,
479	                            format!("Output file selected: {}", path_str),
480	                        );
481	                        self.current_view = View::Compile;
482	                    }
483	                    InputField::CacheFile => {
484	                        self.cache_file = Some(path_str.clone());
485	                        self.log(
486	                            LogLevel::Success,
487	                            format!("Cache file selected: {}", path_str),
488	                        );
489	                        self.current_view = View::Optimize;
490	                    }
491	                    InputField::RouteFile => {
492	                        self.route_file = Some(path_str.clone());
493	                        self.log(
494	                            LogLevel::Success,
495	                            format!("Route file selected: {}", path_str),
496	                        );
497	                        self.current_view = View::Optimize;
498	                    }
499	                    InputField::CleanInputFile => {
500	                        self.clean_input_file = Some(path_str.clone());
501	                        if self.clean_output_file.is_none() {
502	                            let out = path_str
503	                                .replace(".geojson", ".cleaned.geojson")
504	                                .replace(".json", ".cleaned.json");
505	                            self.clean_output_file = Some(out);
506	                        }
507	                        self.log(
508	                            LogLevel::Success,
509	                            format!("Clean input file selected: {}", path_str),
510	                        );
511	                        self.current_view = View::Clean;
512	                    }
513	                    InputField::CleanOutputFile => {
514	                        self.clean_output_file = Some(path_str.clone());
515	                        self.log(
516	                            LogLevel::Success,
517	                            format!("Clean output file selected: {}", path_str),
518	                        );
519	                        self.current_view = View::Clean;
520	                    }
521	                    InputField::VrpWaypointsFile => {
522	                        self.vrp_waypoints_file = Some(path_str.clone());
523	                        self.log(
524	                            LogLevel::Success,
525	                            format!("VRP waypoints file selected: {}", path_str),
526	                        );
527	                        self.current_view = View::Vrp;
528	                    }
529	                    _ => {
530	                        self.current_view = View::Home;
531	                    }
532	                }
533	            }
534	        } else {
535	            // User cancelled — restore the view they came from
536	            self.current_view = previous_view;
537	        }
538	
539	        self.file_browser = None;
540	    }
