542	    pub fn log(&mut self, level: LogLevel, message: impl Into<String>) {
543	        let timestamp = chrono::Local::now().format("%H:%M:%S").to_string();
544	        self.log_entries.push(LogEntry {
545	            timestamp,
546	            level,
547	            message: message.into(),
548	        });
549	        if self.log_entries.len() > 500 {
550	            self.log_entries.remove(0);
551	        }
552	        self.log_scroll = self.log_entries.len().saturating_sub(1);
553	    }
554	
555	    pub fn start_input(&mut self, field: InputField) {
556	        self.input_mode.active = true;
557	        self.input_mode.field = field;
558	        self.input_mode.buffer.clear();
559	    }
560	
561	    pub fn confirm_input(&mut self) {
562	        let value = self.input_mode.buffer.trim().to_string();
563	        if value.is_empty() {
564	            self.input_mode.active = false;
565	            return;
566	        }
567	
568	        match self.input_mode.field.clone() {
569	            InputField::BoundingBox => {
570	                let parts: Vec<&str> = value.split(',').collect();
571	                if parts.len() == 4 {
572	                    if let (Ok(min_lon), Ok(min_lat), Ok(max_lon), Ok(max_lat)) = (
573	                        parts[0].parse::<f64>(),
574	                        parts[1].parse::<f64>(),
575	                        parts[2].parse::<f64>(),
576	                        parts[3].parse::<f64>(),
577	                    ) {
578	                        let bbox = BoundingBox {
579	                            min_lon,
580	                            min_lat,
581	                            max_lon,
582	                            max_lat,
583	                        };
584	                        self.log(LogLevel::Success, format!("Bounding box set: {bbox}"));
585	                        self.bounding_box = Some(bbox);
586	                    } else {
587	                        self.log(LogLevel::Error, "Invalid coordinates".to_string());
588	                    }
589	                } else {
590	                    self.log(
591	                        LogLevel::Error,
592	                        "Expected format: min_lon,min_lat,max_lon,max_lat",
593	                    );
594	                }
595	            }
596	            InputField::InputFile => {
597	                self.input_file = Some(value.clone());
598	                if self.output_file.is_none() {
599	                    let out = value.replace(".geojson", ".rmp").replace(".json", ".rmp");
600	                    self.output_file = Some(out);
601	                }
602	                self.log(LogLevel::Success, format!("Input set: {}", value));
603	            }
604	            InputField::OutputFile => {
605	                self.output_file = Some(value.clone());
606	                self.log(LogLevel::Success, format!("Output set: {}", value));
607	            }
608	            InputField::CacheFile => {
609	                self.cache_file = Some(value.clone());
610	                self.log(LogLevel::Success, format!("Cache file set: {}", value));
611	            }
612	            InputField::RouteFile => {
613	                self.route_file = Some(value.clone());
614	                self.log(LogLevel::Success, format!("Route file set: {}", value));
615	            }
616	            InputField::LeftTurnPenalty => {
617	                if let Ok(v) = value.parse::<f64>() {
618	                    self.turn_penalties.left = v;
619	                    self.log(LogLevel::Success, format!("Left turn penalty set: {}", v));
620	                }
621	            }
622	            InputField::RightTurnPenalty => {
623	                if let Ok(v) = value.parse::<f64>() {
624	                    self.turn_penalties.right = v;
