236	/// Check if a segment should be included based on road classes
237	fn should_include_segment(seg: &OvertureSegment, classes: &[RoadClass]) -> bool {
238	    if classes.is_empty() {
239	        return true;
240	    }
241	
242	    let class_str = seg.class.as_deref().unwrap_or("");
243	
244	    classes.iter().any(|rc| rc.as_str() == class_str)
245	}
