 171	    fn normalize(self, lower: f64, upper: f64) -> f64;
 172	}
 173	
 174	impl NormalizeAngle for f64 {
 175	    fn normalize(self, lower: f64, upper: f64) -> f64 {
 176	        let width = upper - lower;
 177	        let mut val = self;
 178	        while val < lower {
 179	            val += width;
 180	        }
 181	        while val >= upper {
 182	            val -= width;
 183	        }
 184	        val
 185	    }
 186	}
