 837	/// **Theorem (Eulerian circuit exists)**:
 838	/// After the CPP solver adds duplicate edges to make all vertex degrees even,
 839	/// an Eulerian circuit must exist. This is a direct consequence of Euler's theorem:
 840	/// A connected graph has an Eulerian circuit iff every vertex has even degree.
 841	///
 842	/// Test: for any connected graph, after running solve_cpp, verify that the
 843	/// output circuit is a valid closed walk that traverses every edge.
 844	#[test]
 845	fn test_cpp_circuit_is_eulerian() {
 846	    // Triangle graph - already Eulerian (every vertex degree 2)
 847	    let (nodes, edges) = make_graph(
 848	        &[(45.0, -73.0), (45.01, -73.0), (45.005, -73.01)],
 849	        &[
 850	            (0, 1, 1100.0, 0),
 851	            (1, 2, 1100.0, 0),
 852	            (2, 0, 1100.0, 0),
 853	        ],
 854	    );
 855	    let out = solve_cpp(&nodes, &edges, OnewayMode::Ignore, None).unwrap();
 856	
 857	    // Property 1: circuit is non-empty
 858	    assert!(!out.circuit.is_empty(), "circuit must not be empty");
 859	
 860	    // Property 2: circuit is a closed walk (first == last)
 861	    assert_eq!(
 862	        out.circuit.first(), out.circuit.last(),
 863	        "circuit must be closed"
 864	    );
 865	
 866	    // Property 3: every node in the circuit is a valid node index
 867	    for &v in &out.circuit {
 868	        assert!(
 869	            (v as usize) < nodes.len(),
 870	            "circuit node {} out of range (max {})",
 871	            v,
 872	            nodes.len() - 1
 873	        );
 874	    }
 875	
 876	    // Property 4: every consecutive pair in the circuit is connected by an edge
 877	    let mut adj: std::collections::HashSet<(u32, u32)> = std::collections::HashSet::new();
 878	    for e in &edges {
 879	        adj.insert((e.from, e.to));
 880	        if e.oneway == 0 {
 881	            adj.insert((e.to, e.from));
 882	        }
 883	    }
 884	    for window in out.circuit.windows(2) {
 885	        let (a, b) = (window[0], window[1]);
 886	        assert!(
 887	            adj.contains(&(a, b)),
 888	            "circuit edge ({}, {}) is not in the graph",
 889	            a, b
 890	        );
 891	    }
 892	}
