1099	/// **Theorem (Single edge graph)**:
1100	/// The CPP algorithm must handle the degenerate case of a single edge.
1101	/// The circuit should traverse it forward and back (deadhead = edge weight).
1102	#[test]
1103	fn test_cpp_single_edge() {
1104	    let (nodes, edges) = make_graph(
1105	        &[(45.0, -73.0), (45.01, -73.0)],
1106	        &[(0, 1, 1100.0, 0)],
1107	    );
1108	    let out = solve_cpp(&nodes, &edges, OnewayMode::Ignore, None).unwrap();
1109	
1110	    assert!(out.circuit.len() >= 2, "circuit must have at least 2 nodes for 1 edge");
1111	    assert_eq!(out.circuit.first(), out.circuit.last(), "circuit must be closed");
1112	    assert!(out.circuit.contains(&0), "node 0 must appear in circuit");
1113	    assert!(out.circuit.contains(&1), "node 1 must appear in circuit");
1114	
1115	    let edge_km = 1100.0 / 1000.0;
1116	    assert!(
1117	        out.summary.total_distance_km >= edge_km - 0.01,
1118	        "total distance must be at least the edge weight"
1119	    );
1120	}
