 32	/// Compile a GeoJSON road network into the .rmp binary format (filesystem).
 33	pub fn run_compile(req: &CompileRequest) -> anyhow::Result<CompileResult> {
 34	    let start = Instant::now();
 35	
 36	    let mut input_data = Vec::new();
 37	    {
 38	        let mut file = std::fs::File::open(&req.input_geojson)
 39	            .with_context(|| format!("Failed to open input GeoJSON: {}", req.input_geojson))?;
 40	        file.read_to_end(&mut input_data)?;
 41	    }
 42	    let input_size_bytes = input_data.len() as u64;
 43	
 44	    let mut geojson: geojson::FeatureCollection = serde_json::from_slice(&input_data)
 45	        .with_context(|| "Failed to parse GeoJSON FeatureCollection")?;
 46	
 47	    if let Some(ref clean_opts) = req.clean_options {
 48	        let (cleaned_fc, _stats, _warnings) =
 49	            clean_geojson(&geojson, clean_opts).with_context(|| "Failed to clean GeoJSON")?;
 50	        geojson = cleaned_fc;
 51	    }
 52	
 53	    let (buf, node_count, edge_count) =
 54	        build_rmp_buffer(&geojson, req.prune_disconnected)?;
 55	
 56	    // Write output file
 57	    std::fs::write(&req.output_rmp, &buf)
 58	        .with_context(|| format!("Failed to write output file: {}", req.output_rmp))?;
 59	
 60	    let output_size_bytes = buf.len() as u64;
 61	    let elapsed_ms = start.elapsed().as_millis() as u64;
 62	
 63	    Ok(CompileResult {
 64	        input_size_bytes,
 65	        output_size_bytes,
 66	        node_count,
 67	        edge_count,
 68	        elapsed_ms,
 69	    })
 70	}
