 72	/// Build a `.rmp` binary buffer from a parsed GeoJSON FeatureCollection.
 73	///
 74	/// Shared by `run_compile` (and the in-memory compile path).
 75	fn build_rmp_buffer(
 76	    geojson: &geojson::FeatureCollection,
 77	    prune_disconnected: bool,
 78	) -> anyhow::Result<(Vec<u8>, usize, usize)> {
 79	    let mut node_map: HashMap<u64, u32> = HashMap::new();
 80	    let mut nodes: Vec<(f64, f64)> = Vec::new();
 81	    let mut edges: Vec<(u32, u32, f64, u8)> = Vec::new();
 82	
 83	    for feature in &geojson.features {
 84	        let geometry = match feature.geometry.as_ref() {
 85	            Some(g) => g,
 86	            None => continue,
 87	        };
 88	
 89	        let oneway = feature
 90	            .properties
 91	            .as_ref()
 92	            .and_then(|props| props.get("oneway"))
 93	            .and_then(|v| v.as_str())
 94	            .map(|s| if matches!(s, "yes" | "1" | "true") { 1u8 } else { 0u8 })
 95	            .unwrap_or(0);
 96	
 97	        let line_strings: Vec<&Vec<Vec<f64>>> = match &geometry.value {
 98	            geojson::Value::LineString(coords) => vec![coords],
 99	            geojson::Value::MultiLineString(multi) => multi.iter().collect(),
100	            _ => continue,
101	        };
102	
103	        for coords in line_strings {
104	            if coords.len() < 2 { continue; }
105	
106	            let coord_points: Vec<(f64, f64)> = coords
107	                .iter()
108	                .filter(|p| p.len() >= 2)
109	                .map(|p| (p[1], p[0]))
110	                .collect();
111	
112	            if coord_points.len() < 2 { continue; }
113	
114	            let mut last_node_id = None;
115	            for i in 0..coord_points.len() - 1 {
116	                let (lat1, lon1) = coord_points[i];
117	                let (lat2, lon2) = coord_points[i + 1];
118	
119	                let from_node = match last_node_id {
120	                    Some(id) => id,
121	                    None => get_or_create_node(&mut node_map, &mut nodes, lat1, lon1),
122	                };
123	                let to_node = get_or_create_node(&mut node_map, &mut nodes, lat2, lon2);
124	                last_node_id = Some(to_node);
125	
126	                let weight_m = super::haversine_m(lat1, lon1, lat2, lon2);
127	                edges.push((from_node, to_node, weight_m, oneway));
128	            }
129	        }
130	    }
131	
132	    // Prune disconnected subgraphs
133	    if prune_disconnected && !nodes.is_empty() {
134	        prune_disconnected_components(&mut nodes, &mut edges);
135	    }
136	
137	    let node_count = nodes.len();
138	    let edge_count = edges.len();
139	
140	    let mut buf: Vec<u8> = Vec::new();
141	    buf.extend_from_slice(RMP_MAGIC);
142	    buf.extend_from_slice(&(node_count as u32).to_le_bytes());
143	    buf.extend_from_slice(&(edge_count as u32).to_le_bytes());
144	
145	    for (lat, lon) in &nodes {
146	        buf.extend_from_slice(&lat.to_le_bytes());
147	        buf.extend_from_slice(&lon.to_le_bytes());
148	    }
149	
150	    for (from, to, weight_m, oneway) in &edges {
151	        buf.extend_from_slice(&from.to_le_bytes());
152	        buf.extend_from_slice(&to.to_le_bytes());
153	        buf.extend_from_slice(&weight_m.to_le_bytes());
154	        buf.push(*oneway);
155	    }
156	
157	    let crc = crc32fast::hash(&buf);
158	    buf.extend_from_slice(&crc.to_le_bytes());
159	
160	    Ok((buf, node_count, edge_count))
161	}
162	
163	/// Prune disconnected subgraphs, keeping only the largest component.
164	fn prune_disconnected_components(
165	    nodes: &mut Vec<(f64, f64)>,
166	    edges: &mut Vec<(u32, u32, f64, u8)>,
167	) {
168	    let n = nodes.len();
169	    let mut adj: Vec<Vec<u32>> = vec![Vec::new(); n];
170	    for &(from, to, _, _) in edges.iter() {
171	        adj[from as usize].push(to);
172	        adj[to as usize].push(from);
173	    }
174	
175	    let mut visited = vec![false; n];
176	    let mut components: Vec<Vec<u32>> = Vec::new();
177	
178	    for i in 0..n {
179	        if !visited[i] {
180	            let mut comp = Vec::new();
181	            let mut stack = vec![i as u32];
182	            visited[i] = true;
183	            while let Some(node) = stack.pop() {
184	                comp.push(node);
185	                for &neighbor in &adj[node as usize] {
186	                    if !visited[neighbor as usize] {
187	                        visited[neighbor as usize] = true;
188	                        stack.push(neighbor);
189	                    }
190	                }
191	            }
192	            components.push(comp);
193	        }
194	    }
195	
196	    if components.len() <= 1 { return; }
197	
198	    components.sort_by_key(|c| std::cmp::Reverse(c.len()));
199	    let largest = &components[0];
200	
201	    let mut old_to_new = vec![None; n];
202	    let mut new_nodes = Vec::with_capacity(largest.len());
203	    for &old_id in largest {
204	        old_to_new[old_id as usize] = Some(new_nodes.len() as u32);
205	        new_nodes.push(nodes[old_id as usize]);
206	    }
207	
208	    let mut new_edges = Vec::new();
209	    for &(from, to, weight, oneway) in edges.iter() {
210	        if let (Some(nf), Some(nt)) = (old_to_new[from as usize], old_to_new[to as usize]) {
211	            new_edges.push((nf, nt, weight, oneway));
212	        }
213	    }
214	
215	    *nodes = new_nodes;
216	    *edges = new_edges;
217	}
