219	/// Quick validation: check if a file starts with the RMP magic bytes.
220	#[allow(dead_code)]
221	pub fn is_rmp_file(data: &[u8]) -> bool {
222	    data.len() >= 4 && &data[..4] == RMP_MAGIC
223	}
224	
225	/// Get or create a node ID for the given (lat, lon) coordinates.
226	fn get_or_create_node(
227	    node_map: &mut HashMap<u64, u32>,
228	    nodes: &mut Vec<(f64, f64)>,
229	    lat: f64,
230	    lon: f64,
231	) -> u32 {
232	    let lat_i = (lat * 1e6) as i32;
233	    let lon_i = (lon * 1e6) as i32;
234	    let key = ((lat_i as u64) << 32) | (lon_i as u32 as u64);
235	
236	    *node_map.entry(key).or_insert_with(|| {
237	        let id = nodes.len() as u32;
238	        nodes.push((lat, lon));
239	        id
240	    })
241	}
