1203	async fn handle_vrp_solve(args: &Value) -> Result<Value> {
1204	    let stops_val = args
1205	        .get("stops")
1206	        .and_then(|v| v.as_array())
1207	        .ok_or_else(|| anyhow::anyhow!("Missing 'stops' parameter"))?;
1208	
1209	    if stops_val.is_empty() {
1210	        anyhow::bail!("At least one stop (the depot) is required");
1211	    }
1212	
1213	    let stops: Vec<VRPSolverStop> = stops_val
1214	        .iter()
1215	        .enumerate()
1216	        .map(|(i, s)| {
1217	            let lat = s.get("lat").and_then(|v| v.as_f64())
1218	                .ok_or_else(|| anyhow::anyhow!("Stop {} missing 'lat'", i))?;
1219	            let lon = s.get("lon").and_then(|v| v.as_f64())
1220	                .ok_or_else(|| anyhow::anyhow!("Stop {} missing 'lon'", i))?;
1221	            let label = s.get("label").and_then(|v| v.as_str())
1222	                .unwrap_or_else(|| "")
1223	                .to_string();
1224	            let demand = s.get("demand").and_then(|v| v.as_f64());
1225	            Ok(VRPSolverStop {
1226	                lat,
1227	                lon,
1228	                label: if label.is_empty() { format!("Stop {}", i) } else { label },
1229	                demand,
1230	                arrival_time: None,
1231	            })
1232	        })
1233	        .collect::<Result<Vec<_>>>()?;
1234	
1235	    let num_vehicles = args.get("num_vehicles").and_then(|v| v.as_u64()).unwrap_or(1) as usize;
1236	    let vehicle_capacity = args.get("vehicle_capacity").and_then(|v| v.as_f64()).unwrap_or(100.0);
1237	    let solver_id = args.get("solver_id").and_then(|v| v.as_str()).unwrap_or("default").to_string();
1238	    let avg_speed_kmh = args.get("avg_speed_kmh").and_then(|v| v.as_f64()).unwrap_or(40.0);
1239	    let objective = match args.get("objective").and_then(|v| v.as_str()).unwrap_or("min_distance") {
1240	        "min_time" => VrpObjective::MinTime,
1241	        "balance_load" => VrpObjective::BalanceLoad,
1242	        "min_vehicles" => VrpObjective::MinVehicles,
1243	        _ => VrpObjective::MinDistance,
1244	    };
1245	
1246	    // Build haversine distance matrix
1247	    let matrix = build_haversine_matrix(&stops, avg_speed_kmh);
1248	
1249	    let input = VRPSolverInput {
1250	        locations: stops,
1251	        num_vehicles,
1252	        vehicle_capacity,
1253	        objective,
1254	        matrix: Some(matrix),
1255	        service_time_secs: None,
1256	        use_time_windows: false,
1257	        window_open: None,
1258	        window_close: None,
1259	    };
