193	#[async_trait::async_trait]
194	impl VRPSolver for ClarkeWrightSolver {
195	    fn id(&self) -> &str {
196	        "clarke_wright"
197	    }
198	    fn label(&self) -> &str {
199	        "Clarke-Wright Savings"
200	    }
