206	        let matrix = input
207	            .matrix
208	            .as_ref()
209	            .ok_or("Clarke-Wright solver requires a distance matrix")?;
210	        let result = solve(matrix, input.num_vehicles);
211	        Ok(result.into_output(input))
212	    }
213	    fn clone_box(&self) -> Box<dyn VRPSolver> {
214	        Box::new(ClarkeWrightSolver)
215	    }
216	}
