 9	async fn main() -> anyhow::Result<()> {
10	    // No arguments = launch the TUI; any arguments = CLI mode
11	    if std::env::args().len() == 1 {
12	        run_tui().await
13	    } else {
14	        cli::run().await?;
15	        Ok(())
16	    }
17	}
