 65	}
 66	
 67	impl FileBrowser {
 68	    pub fn new(target_field: InputField, previous_view: View) -> Self {
 69	        let current_path = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
 70	        Self {
 71	            current_path,
 72	            entries: Vec::new(),
 73	            selection: 0,
 74	            filter: match target_field {
 75	                InputField::InputFile | InputField::CleanInputFile => FileFilter::GeoJson,
 76	                InputField::CacheFile | InputField::VrpWaypointsFile => FileFilter::Rmp,
 77	                _ => FileFilter::All,
 78	            },
 79	            target_field,
 80	            show_hidden: false,
 81	            previous_view,
 82	        }
 83	    }
 84	
 85	    pub fn refresh_entries(&mut self) -> anyhow::Result<()> {
 86	        self.entries.clear();
 87	
 88	        // Add parent directory entry if not at root
 89	        if let Some(parent) = self.current_path.parent() {
 90	            self.entries.push(FileEntry {
 91	                name: "..".to_string(),
 92	                path: parent.to_path_buf(),
 93	                is_dir: true,
 94	                size: None,
 95	                modified: None,
 96	            });
 97	        }
 98	
 99	        // Read directory entries
100	        let read_dir = std::fs::read_dir(&self.current_path)?;
101	        let mut entries: Vec<FileEntry> = Vec::new();
102	
103	        for entry in read_dir.flatten() {
104	            let path = entry.path();
105	            let name = entry.file_name().to_string_lossy().to_string();
106	
107	            // Skip hidden files unless show_hidden is true
108	            if !self.show_hidden && name.starts_with('.') {
109	                continue;
110	            }
111	
112	            let metadata = entry.metadata().ok();
113	            let is_dir = metadata.as_ref().map(|m| m.is_dir()).unwrap_or(false);
114	            let size = metadata
115	                .as_ref()
116	                .and_then(|m| if !is_dir { Some(m.len()) } else { None });
117	            let modified = metadata.as_ref().and_then(|m| m.modified().ok());
118	
119	            // Include directories and files matching filter
120	            if is_dir || self.filter.matches(&path) {
121	                entries.push(FileEntry {
122	                    name,
123	                    path,
124	                    is_dir,
125	                    size,
126	                    modified,
127	                });
128	            }
129	        }
130	
131	        // Sort: directories first, then by name
132	        entries.sort_by(|a, b| match (a.is_dir, b.is_dir) {
133	            (true, false) => std::cmp::Ordering::Less,
134	            (false, true) => std::cmp::Ordering::Greater,
135	            _ => a.name.to_lowercase().cmp(&b.name.to_lowercase()),
136	        });
137	
138	        self.entries.extend(entries);
139	
140	        // Reset selection if out of bounds
141	        if self.selection >= self.entries.len() && !self.entries.is_empty() {
142	            self.selection = 0;
143	        }
144	
145	        Ok(())
146	    }
147	
148	    pub fn navigate_up(&mut self) {
149	        if !self.entries.is_empty() {
150	            self.selection = self.selection.saturating_sub(1);
151	        }
152	    }
153	
154	    pub fn navigate_down(&mut self) {
155	        if !self.entries.is_empty() {
156	            self.selection = (self.selection + 1).min(self.entries.len() - 1);
157	        }
158	    }
159	
160	    pub fn select_entry(&mut self) -> Option<PathBuf> {
161	        if self.entries.is_empty() {
162	            return None;
163	        }
164	
165	        let entry = &self.entries[self.selection];
166	
167	        if entry.is_dir {
168	            // Navigate into directory
169	            self.current_path = entry.path.clone();
170	            self.selection = 0;
171	            let _ = self.refresh_entries();
172	            None
173	        } else {
174	            // Return selected file path
175	            Some(entry.path.clone())
176	        }
177	    }
178	
179	    pub fn go_parent(&mut self) {
180	        if let Some(parent) = self.current_path.parent() {
181	            self.current_path = parent.to_path_buf();
182	            self.selection = 0;
183	            let _ = self.refresh_entries();
184	        }
185	    }
186	}
