115	/// Run OSM PBF extraction
116	async fn run_osm_extract(req: &ExtractRequest) -> anyhow::Result<ExtractResult> {
117	    use crate::core::osm::{segment_to_feature, BBox as OsmBBox, OsmExtractor, OverpassExtractor};
118	
119	    let bbox = OsmBBox {
120	        min_lon: req.bbox.min_lon,
121	        min_lat: req.bbox.min_lat,
122	        max_lon: req.bbox.max_lon,
123	        max_lat: req.bbox.max_lat,
124	    };
125	    let classes: Vec<String> = req
126	        .road_classes
127	        .iter()
128	        .map(|rc| rc.as_str().to_string())
129	        .collect();
130	
131	    // Priority: 1. CLI/Request path, 2. Env var, 3. Default file, 4. Overpass API
132	    let pbf_path_candidate = req.pbf_path.clone()
133	        .or_else(|| std::env::var("OSM_PBF_PATH").ok());
134	
135	    let segments = if let Some(pbf_path) = pbf_path_candidate {
136	        if std::path::Path::new(&pbf_path).exists() {
137	            tracing::info!("Using local PBF file: {}", pbf_path);
138	            let extractor = OsmExtractor::new(pbf_path)?;
139	            extractor.extract_bbox(&bbox, &classes)?
140	        } else {
141	            tracing::info!("PBF file not found at {}, falling back to Overpass", pbf_path);
142	            let extractor = OverpassExtractor::new();
143	            extractor.extract_bbox(&bbox, &classes).await?
144	        }
145	    } else if std::path::Path::new("monaco.osm.pbf").exists() {
146	        tracing::info!("Using default PBF file: monaco.osm.pbf");
147	        let extractor = OsmExtractor::new("monaco.osm.pbf".to_string())?;
148	        extractor.extract_bbox(&bbox, &classes)?
149	    } else {
150	        tracing::info!("No PBF file found, using Overpass API");
151	        let extractor = OverpassExtractor::new();
152	        extractor.extract_bbox(&bbox, &classes).await?
153	    };
154	
155	    let features: Vec<Feature> = segments.into_iter().map(segment_to_feature).collect();
156	
157	    // Build graph statistics
158	    let (nodes, edges, total_km) = build_graph_stats(&features)?;
159	
160	    // Write GeoJSON output
161	    let geojson = FeatureCollection {
162	        bbox: None,
163	        features,
164	        foreign_members: None,
165	    };
166	
167	    let geojson_string = serde_json::to_string_pretty(&geojson)?;
168	    let output_path = &req.output_path;
169	
170	    std::fs::File::create(output_path)?
171	        .write_all(geojson_string.as_bytes())
172	        .context("Failed to write GeoJSON output")?;
173	
174	    Ok(ExtractResult {
175	        nodes,
176	        edges,
177	        total_km,
178	        output_path: output_path.clone(),
179	    })
180	}
