320	/// Build graph statistics from features
321	fn build_graph_stats(features: &[Feature]) -> Result<(usize, usize, f64)> {
322	    // Node deduplication: snap coordinates to ~1m precision
323	    let mut node_map: HashMap<(i64, i64), usize> = HashMap::new();
324	    let mut next_node_id: usize = 0;
325	    let mut edge_count = 0;
326	    let mut total_km = 0.0;
327	
328	    for f in features {
329	        if let Some(ref geom) = f.geometry {
330	            let line_strings: Vec<&Vec<Vec<f64>>> = match &geom.value {
331	                GeoJsonValue::LineString(coords) => vec![coords],
332	                GeoJsonValue::MultiLineString(multi) => multi.iter().collect(),
333	                _ => continue,
334	            };
335	
336	            for coords in line_strings {
337	                if coords.len() < 2 {
338	                    continue;
339	                }
340	
341	                // Extract coordinates as (lon, lat) pairs
342	                let coord_points: Vec<(f64, f64)> = coords
343	                    .iter()
344	                    .filter(|p| p.len() >= 2)
345	                    .map(|p| (p[0], p[1]))
346	                    .collect();
347	
348	                // Calculate length for each segment
349	                for window in coord_points.windows(2) {
350	                    let (lon1, lat1) = window[0];
351	                    let (lon2, lat2) = window[1];
352	
353	                    // Haversine distance in km
354	                    let d = super::haversine_m(lat1, lon1, lat2, lon2) / 1000.0;
355	                    total_km += d;
356	
357	                    // Get/create node IDs
358	                    let _node1 = get_or_create_node(&mut node_map, &mut next_node_id, lon1, lat1);
359	                    let _node2 = get_or_create_node(&mut node_map, &mut next_node_id, lon2, lat2);
360	
361	                    // Count edge
362	                    edge_count += 1;
363	                }
364	            }
365	        }
366	    }
367	
368	    Ok((node_map.len(), edge_count, total_km))
369	}
370	
371	/// Get or create a node ID for given coordinates
372	fn get_or_create_node(
373	    node_map: &mut HashMap<(i64, i64), usize>,
374	    next_node_id: &mut usize,
375	    lon: f64,
376	    lat: f64,
377	) -> usize {
378	    // Snap to ~1m precision (6 decimal places)
379	    let key = ((lon * 1e6) as i64, (lat * 1e6) as i64);
380	    *node_map.entry(key).or_insert_with(|| {
381	        let id = *next_node_id;
382	        *next_node_id += 1;
383	        id
384	    })
385	}
