   7	/// Filter nodes and edges to only those within a bounding box.
   8	/// Returns remapped (nodes, edges) where edge indices are renumbered from 0.
   9	/// If `bbox` is `None`, returns the originals unchanged.
  10	#[allow(dead_code)]
  11	pub fn filter_bbox(
  12	    nodes: &[RmpNode],
  13	    edges: &[RmpEdge],
  14	    bbox: Option<(f64, f64, f64, f64)>, // (min_lat, max_lat, min_lon, max_lon)
  15	) -> (Vec<RmpNode>, Vec<RmpEdge>) {
  16	    let Some((min_lat, max_lat, min_lon, max_lon)) = bbox else {
  17	        return (nodes.to_vec(), edges.to_vec());
  18	    };
  19	
  20	    // Mark which old-node indices are inside the bbox
  21	    let inside: Vec<bool> = nodes
  22	        .iter()
  23	        .map(|n| n.lat >= min_lat && n.lat <= max_lat && n.lon >= min_lon && n.lon <= max_lon)
  24	        .collect();
  25	
  26	    // Build old->new index map
  27	    let mut old_to_new = vec![u32::MAX; nodes.len()];
  28	    let mut new_nodes = Vec::new();
  29	    let mut next: u32 = 0;
  30	    for (i, &is_inside) in inside.iter().enumerate() {
  31	        if is_inside {
  32	            old_to_new[i] = next;
  33	            new_nodes.push(nodes[i]);
  34	            next += 1;
  35	        }
  36	    }
  37	
  38	    // Keep edges whose both endpoints are inside
  39	    let new_edges: Vec<RmpEdge> = edges
  40	        .iter()
  41	        .filter(|e| {
  42	            let from_inside = inside.get(e.from as usize).copied().unwrap_or(false);
  43	            let to_inside = inside.get(e.to as usize).copied().unwrap_or(false);
  44	            from_inside && to_inside
  45	        })
  46	        .map(|e| RmpEdge {
  47	            from: old_to_new[e.from as usize],
  48	            to: old_to_new[e.to as usize],
  49	            weight_m: e.weight_m,
  50	            oneway: e.oneway,
  51	        })
  52	        .collect();
  53	
  54	    (new_nodes, new_edges)
  55	}
