1018	/// **Theorem (Deadhead correctness on non-Eulerian graphs)**:
1019	/// If the graph is not Eulerian, the CPP solver must add deadhead edges.
1020	/// The total distance must equal the sum of original edge weights plus
1021	/// deadhead distance. This is a conservation law.
1022	#[test]
1023	fn test_cpp_distance_conservation() {
1024	    // Path graph (non-Eulerian): A-B-C
1025	    let (nodes, edges) = make_graph(
1026	        &[(45.0, -73.0), (45.01, -73.0), (45.02, -73.0)],
1027	        &[
1028	            (0, 1, 1100.0, 0),
1029	            (1, 2, 1100.0, 0),
1030	        ],
1031	    );
1032	    let out = solve_cpp(&nodes, &edges, OnewayMode::Ignore, None).unwrap();
1033	
1034	    let sum_weights_km: f64 = edges.iter().map(|e| e.weight_m / 1000.0).sum();
1035	    let expected_total = sum_weights_km + out.summary.deadhead_distance_km;
1036	    let tolerance = 0.01;
1037	
1038	    assert!(
1039	        (out.summary.total_distance_km - expected_total).abs() < tolerance,
1040	        "distance conservation: total ({:.6}) should equal original ({:.6}) + deadhead ({:.6})",
1041	        out.summary.total_distance_km, sum_weights_km, out.summary.deadhead_distance_km
1042	    );
1043	
1044	    assert!(
1045	        out.summary.deadhead_distance_km > 0.0,
1046	        "non-Eulerian graph must have positive deadhead, got 0"
1047	    );
1048	}
