1136	        .and_then(|v| v.as_str())
1137	        .ok_or_else(|| anyhow::anyhow!("Missing 'output' parameter"))?
1138	        .to_string();
1139	
1140	    // Build CleanOptions from args, using defaults where not specified
1141	    let defaults = CleanOptions::default();
1142	    let options = CleanOptions {
1143	        make_valid: args.get("make_valid").and_then(|v| v.as_bool()).unwrap_or(defaults.make_valid),
1144	        drop_invalid: args.get("drop_invalid").and_then(|v| v.as_bool()).unwrap_or(defaults.drop_invalid),
