1518	        .get("base_consumption")
1519	        .and_then(|v| v.as_f64())
1520	        .unwrap_or(0.08);
1521	
1522	    // Build an ElevationProfile from the samples
1523	    let points: Vec<v2rmp::core::elevation::RouteElevationPoint> = samples_val
1524	        .iter()
1525	        .enumerate()
1526	        .map(|(i, s)| {
