1563	// ── Inspect RMP handler ──────────────────────────────────────────────────
1564	
1565	fn handle_inspect_rmp(args: &Value) -> Result<Value> {
1566	    let input = args
1567	        .get("input")
1568	        .and_then(|v| v.as_str())
1569	        .ok_or_else(|| anyhow::anyhow!("Missing 'input' parameter"))?;
1570	
1571	    let file_data = std::fs::read(input)
1572	        .map_err(|e| anyhow::anyhow!("Failed to read .rmp file: {}", e))?;
1573	
1574	    let (nodes, edges) = v2rmp::core::optimize::read_rmp_file(&file_data)?;
1575	
1576	    // Compute bounding box from nodes
1577	    let (min_lat, max_lat, min_lon, max_lon) = if nodes.is_empty() {
1578	        (0.0, 0.0, 0.0, 0.0)
1579	    } else {
1580	        nodes.iter().fold(
1581	            (f64::MAX, f64::MIN, f64::MAX, f64::MIN),
1582	            |(mn_lat, mx_lat, mn_lon, mx_lon), n| {
1583	                (mn_lat.min(n.lat), mx_lat.max(n.lat), mn_lon.min(n.lon), mx_lon.max(n.lon))
1584	            },
1585	        )
1586	    };
1587	
1588	    let total_edge_length_km: f64 = edges.iter().map(|e| e.weight_m / 1000.0).sum();
1589	
1590	    Ok(json!({
1591	        "node_count": nodes.len(),
1592	        "edge_count": edges.len(),
1593	        "bbox": {
1594	            "min_lat": min_lat,
1595	            "max_lat": max_lat,
1596	            "min_lon": min_lon,
1597	            "max_lon": max_lon,
1598	        },
1599	        "total_edge_length_km": total_edge_length_km,
1600	        "file_size_bytes": file_data.len(),
1601	    }))
1602	}
