137	/// Default model path relative to the executable.
138	pub fn default_model_path() -> std::path::PathBuf {
139	    std::env::current_exe()
140	        .unwrap_or_else(|_| std::path::PathBuf::from("."))
141	        .parent()
142	        .unwrap_or(std::path::Path::new("."))
143	        .join("models")
144	        .join("solver_selector.safetensors")
145	}
