259	    /// Translates a natural language query into a VRP JSON string using the LLM.
260	    pub fn parse_llm(&mut self, query: &str) -> Result<String> {
261	        let system_prompt = "You are an expert route optimization assistant. Convert the user's natural language routing query into a valid JSON object describing the Vehicle Routing Problem (VRP) configuration. Extract: 'num_stops', 'num_vehicles', 'depot' (as {\"lat\": .., \"lon\": ..}), 'deadline' (HH:MM), 'capacity', 'variant' (e.g., 'cvrp', 'cvrptw'). ONLY output valid JSON and nothing else.";
262	        
263	        let prompt = format!("<|im_start|>system\n{}<|im_end|>\n<|im_start|>user\n{}<|im_end|>\n<|im_start|>assistant\n", system_prompt, query);
264	
265	        let tokens = self.tokenizer.encode(prompt, true)
266	            .map_err(|e| anyhow::anyhow!("Tokenization error: {}", e))?;
267	        let mut tokens = tokens.get_ids().to_vec();
268	
269	        let mut logits_processor = LogitsProcessor::new(1337, None, None);
270	        let mut output_text = String::new();
271	
272	        let mut pos = 0;
273	        let max_tokens = 256;
274	        for index in 0..max_tokens {
275	            let context_size = if index == 0 { tokens.len() } else { 1 };
276	            let start_pos = tokens.len().saturating_sub(context_size);
277	            let input = Tensor::new(&tokens[start_pos..], &self.device)?.unsqueeze(0)?;
278	            
279	            let logits = self.model.forward(&input, pos)?;
280	            let logits = logits.squeeze(0)?;
281	            let logits = logits.get(logits.dim(0)? - 1)?;
282	
283	            let next_token = logits_processor.sample(&logits)?;
284	            tokens.push(next_token);
285	            pos += context_size;
286	
287	            if let Some(text) = self.tokenizer.decode(&[next_token], true).ok() {
288	                output_text.push_str(&text);
289	                if output_text.contains("<|im_end|>") {
290	                    break;
291	                }
292	            }
293	        }
294	
295	        let clean_json = output_text.replace("<|im_end|>", "").trim().to_string();
296	        Ok(clean_json)
297	    }
298	}
