 3	/// Canonical bounding box for spatial queries.
 4	///
 5	/// This is the single source of truth — used by osm, overture, elevation,
 6	/// extract, and everywhere else that needs lat/lon bounding boxes.
 7	#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq)]
 8	pub struct BBox {
 9	    pub min_lon: f64,
10	    pub min_lat: f64,
11	    pub max_lon: f64,
12	    pub max_lat: f64,
13	}
14	
15	impl BBox {
16	    /// Check if a point is within the bounding box.
17	    pub fn contains(&self, lon: f64, lat: f64) -> bool {
18	        lon >= self.min_lon && lon <= self.max_lon && lat >= self.min_lat && lat <= self.max_lat
19	    }
20	
21	    /// Check if another bbox intersects this one.
22	    pub fn intersects(&self, other: &BBox) -> bool {
23	        !(self.max_lon < other.min_lon
24	            || self.min_lon > other.max_lon
25	            || self.max_lat < other.min_lat
26	            || self.min_lat > other.max_lat)
27	    }
28	
29	    /// Approximate area in degrees squared.
30	    #[allow(dead_code)]
31	    pub fn area(&self) -> f64 {
32	        (self.max_lon - self.min_lon) * (self.max_lat - self.min_lat)
33	    }
34	}
